-- Taiwan: ES/DE/FR milestone translations, hand-translated from the
-- English rows in 340_taiwan_milestones.sql. Proper nouns, regulation/
-- format names, and institution abbreviations (eGUI, MIG, MOF, TWD,
-- BTA) stay untranslated, matching the convention used for
-- RR/BIR/TRAIN Law in the Philippines migrations.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-foreign-provider-vat-2017', 'es', 'El régimen de servicios digitales transfronterizos incorpora a los proveedores extranjeros al ámbito del IVA/eGUI', 'El Reglamento de Taiwán para la Recaudación del IVA sobre Servicios Electrónicos Transfronterizos Prestados por Empresas Extranjeras entró en vigor el 1 de mayo de 2017, exigiendo que los proveedores extranjeros de servicios digitales que superaran un umbral de registro se inscribieran a efectos del IVA y comenzaran a declarar, con obligaciones de emisión de Factura Uniforme Gubernamental electrónica (eGUI) para estos registrados en los años siguientes. Esto estableció la parte transfronteriza de lo que se convirtió en un mandato doméstico universal en 2021; no creó todavía ninguna obligación para las empresas nacionales.', '["No se requiere ninguna acción para las empresas nacionales en esta etapa.", "Los proveedores extranjeros de servicios digitales que venden a Taiwán deben confirmar si el umbral de registro les aplica."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-mandate-2021', 'es', 'El eGUI se vuelve obligatorio para todas las entidades registradas a efectos del impuesto empresarial', 'Desde el 1 de enero de 2021, todas las entidades registradas a efectos del impuesto empresarial en Taiwán -- nacionales y extranjeras -- deben emitir Facturas Uniformes Gubernamentales electrónicas (eGUI) en formato estructurado, cubriendo tanto transacciones B2B como B2C. Esta es la fecha clave del mandato universal: trasladó el eGUI de un requisito transfronterizo y de adopción gradual a una obligación general para toda la población de empresas registradas a efectos fiscales, administrada por la Plataforma de Facturación Electrónica del Ministerio de Finanzas (operada junto con la Agencia de Información Fiscal).', '["Confirme que su sistema de facturación emite registros eGUI estructurados a través de la plataforma del MOF en lugar de facturas en papel o PDF sin estructurar.", "Regístrese en la plataforma de facturación electrónica de la Agencia de Información Fiscal si aún no lo ha hecho.", "Las empresas extranjeras sin presencia en Taiwán deben confirmar que su agente local o socio de facturación certificado presenta las declaraciones en su nombre."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-bta-amendment-2024', 'es', 'La enmienda de la Ley del Impuesto Empresarial fija plazos de transmisión y sanciones', 'Una enmienda a la Ley del Impuesto al Valor Agregado y No Valor Agregado (Business Tax Act), publicada el 3 de septiembre de 2024, formalizó los plazos de transmisión para los eGUI ya vigentes: las facturas B2B deben transmitirse a la plataforma del MOF dentro de 7 días naturales, y las facturas B2C dentro de 2 días naturales. También reforzó las sanciones por transmisión tardía o faltante y por datos de factura inexactos, con multas que van de TWD 1.500 a TWD 15.000 y sanciones crecientes por infracciones repetidas. Se trata de un cambio procedimental y de cumplimiento -- no altera quién está cubierto por el mandato universal de 2021.', '["Confirme que su flujo de facturación transmite los eGUI B2B dentro de 7 días y los B2C dentro de 2 días desde su emisión.", "Revise los procedimientos de corrección de errores -- los datos transmitidos inexactos pueden generar sanciones distintas de las multas por transmisión tardía.", "Prevea multas de TWD 1.500-15.000 por infracción como riesgo de cumplimiento si los procesos de transmisión no están automatizados."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-mig4-mandatory-2026', 'es', 'El MIG 4.0 se convierte en el único formato válido de eGUI', 'La Guía de Implementación de Mensajes (MIG) versión 4.0 se introdujo como el nuevo estándar de formato XML para el eGUI a partir del 1 de enero de 2024, funcionando en paralelo con los formatos MIG 3.1/3.2 anteriores durante un período de transición. Ese período de transición finalizó el 31 de diciembre de 2025 -- desde el 1 de enero de 2026, ya no se aceptan las presentaciones en MIG 3.1/3.2 y el MIG 4.0 es el único formato válido para la transmisión de eGUI. Se trata de una actualización técnica de formato, no de un cambio en quién está cubierto por el mandato.', '["Confirme que la salida eGUI de su sistema de facturación o ERP se ha actualizado a MIG 4.0 -- las presentaciones en MIG 3.1/3.2 ya son rechazadas.", "Si un proveedor de software o un prestador de servicios certificado gestiona la transmisión en su nombre, confirme que completó la migración a MIG 4.0 antes del cambio."]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-foreign-provider-vat-2017', 'de', 'Die Regelung für grenzüberschreitende digitale Dienstleistungen bringt ausländische Anbieter in den Anwendungsbereich von USt/eGUI', 'Taiwans Verordnung zur Erhebung der Umsatzsteuer auf grenzüberschreitende elektronische Dienstleistungen ausländischer Unternehmen trat am 1. Mai 2017 in Kraft und verpflichtete ausländische Anbieter digitaler Dienstleistungen, die eine Registrierungsschwelle überschritten, sich für die Umsatzsteuer zu registrieren und Meldungen abzugeben; die Pflicht zur Ausstellung elektronischer Government Uniform Invoices (eGUI) für diese registrierten Anbieter folgte in den darauffolgenden Jahren. Damit wurde der grenzüberschreitende Teil dessen geschaffen, was 2021 zu einem universellen inländischen Mandat wurde; für inländische Unternehmen entstand daraus noch keine Pflicht.', '["Für inländische Unternehmen ist in dieser Phase noch keine Maßnahme erforderlich.", "Ausländische Anbieter digitaler Dienstleistungen, die nach Taiwan verkaufen, sollten prüfen, ob die Registrierungsschwelle für sie gilt."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-mandate-2021', 'de', 'eGUI wird für alle umsatzsteuerlich registrierten Unternehmen verpflichtend', 'Ab dem 1. Januar 2021 müssen alle umsatzsteuerlich registrierten Unternehmen in Taiwan -- inländische und ausländische -- elektronische Government Uniform Invoices (eGUI) in strukturiertem Format ausstellen, sowohl für B2B- als auch für B2C-Transaktionen. Dies ist das zentrale Datum des universellen Mandats: Es machte aus einer zunächst grenzüberschreitenden und schrittweise eingeführten Pflicht eine flächendeckende Verpflichtung für die gesamte steuerlich registrierte Unternehmenspopulation, verwaltet über die E-Invoice-Plattform des Finanzministeriums (betrieben gemeinsam mit der Fiscal Information Agency).', '["Prüfen Sie, ob Ihr Rechnungssystem strukturierte eGUI-Datensätze über die MOF-Plattform ausstellt und nicht Papier- oder unstrukturierte PDF-Rechnungen.", "Registrieren Sie sich bei der E-Invoice-Plattform der Fiscal Information Agency, falls noch nicht erfolgt.", "Ausländische Unternehmen ohne Präsenz in Taiwan sollten prüfen, ob ihr lokaler Vertreter oder zertifizierter Rechnungsdienstleister die Meldungen für sie einreicht."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-bta-amendment-2024', 'de', 'Änderung des Business Tax Act legt Übermittlungsfristen und Sanktionen fest', 'Eine am 3. September 2024 veröffentlichte Änderung des Umsatzsteuergesetzes (Business Tax Act) formalisierte die bereits geltenden Übermittlungsfristen für eGUI: B2B-Rechnungen müssen innerhalb von 7 Kalendertagen an die MOF-Plattform übermittelt werden, B2C-Rechnungen innerhalb von 2 Kalendertagen. Zudem wurden die Sanktionen für verspätete oder fehlende Übermittlung sowie für ungenaue Rechnungsdaten verschärft, mit Bußgeldern zwischen TWD 1.500 und TWD 15.000 und steigenden Sanktionen bei wiederholten Verstößen. Es handelt sich um eine verfahrens- und durchsetzungsbezogene Änderung -- der Kreis der vom universellen Mandat von 2021 erfassten Unternehmen bleibt unverändert.', '["Prüfen Sie, ob Ihr Rechnungsworkflow B2B-eGUI innerhalb von 7 Tagen und B2C-eGUI innerhalb von 2 Tagen nach Ausstellung übermittelt.", "Überprüfen Sie Fehlerkorrekturverfahren -- ungenaue übermittelte Daten können separate Sanktionen zu den Fristversäumnis-Bußgeldern auslösen.", "Kalkulieren Sie Bußgelder von TWD 1.500-15.000 pro Verstoß als Compliance-Risiko ein, falls die Übermittlungsprozesse nicht automatisiert sind."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-mig4-mandatory-2026', 'de', 'MIG 4.0 wird zum einzig gültigen eGUI-Format', 'Die Message Implementation Guideline (MIG) Version 4.0 wurde ab dem 1. Januar 2024 als neuer XML-Formatstandard für eGUI eingeführt und lief während einer Übergangsphase parallel zu den älteren Formaten MIG 3.1/3.2. Diese Übergangsphase endete am 31. Dezember 2025 -- seit dem 1. Januar 2026 werden Einreichungen im Format MIG 3.1/3.2 nicht mehr akzeptiert, und MIG 4.0 ist das einzig gültige Format für die eGUI-Übermittlung. Dies ist eine technische Formatumstellung, keine Änderung des vom Mandat erfassten Personenkreises.', '["Prüfen Sie, ob die eGUI-Ausgabe Ihres Rechnungs- oder ERP-Systems auf MIG 4.0 umgestellt wurde -- Einreichungen im Format MIG 3.1/3.2 werden inzwischen abgelehnt.", "Falls ein Softwareanbieter oder zertifizierter Dienstleister die Übermittlung für Sie übernimmt, bestätigen Sie, dass die MIG-4.0-Umstellung vor der Umstellungsfrist abgeschlossen wurde."]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-foreign-provider-vat-2017', 'fr', 'Le régime des services numériques transfrontaliers fait entrer les fournisseurs étrangers dans le champ de la TVA/eGUI', 'Le règlement taïwanais régissant la collecte de la TVA sur les services électroniques transfrontaliers fournis par des entreprises étrangères est entré en vigueur le 1er mai 2017, exigeant que les fournisseurs étrangers de services numériques dépassant un seuil d''enregistrement s''inscrivent à la TVA et commencent à déclarer, les obligations d''émission de Factures Uniformes Gouvernementales électroniques (eGUI) pour ces entités enregistrées suivant au cours des années suivantes. Cela a établi le volet transfrontalier de ce qui est devenu un mandat national universel en 2021 ; cela n''a créé, à ce stade, aucune obligation pour les entreprises nationales.', '["Aucune action requise pour les entreprises nationales à ce stade.", "Les fournisseurs étrangers de services numériques vendant vers Taïwan doivent vérifier si le seuil d''enregistrement leur est applicable."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-mandate-2021', 'fr', 'L''eGUI devient obligatoire pour toutes les entités enregistrées à la taxe professionnelle', 'À compter du 1er janvier 2021, toutes les entités enregistrées à la taxe professionnelle à Taïwan -- nationales et étrangères -- doivent émettre des Factures Uniformes Gouvernementales électroniques (eGUI) au format structuré, couvrant les transactions B2B comme B2C. C''est la date phare du mandat universel : elle a fait passer l''eGUI d''une obligation transfrontalière et d''adoption progressive à une obligation générale pour l''ensemble des entreprises enregistrées fiscalement, administrée par la plateforme de facturation électronique du ministère des Finances (exploitée avec la Fiscal Information Agency).', '["Vérifiez que votre système de facturation émet des enregistrements eGUI structurés via la plateforme du MOF plutôt que des factures papier ou PDF non structurées.", "Enregistrez-vous auprès de la plateforme de facturation électronique de la Fiscal Information Agency si ce n''est pas déjà fait.", "Les entreprises étrangères sans présence à Taïwan doivent vérifier que leur agent local ou prestataire de facturation certifié déclare en leur nom."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-bta-amendment-2024', 'fr', 'L''amendement de la loi sur la taxe professionnelle fixe des délais de transmission et des sanctions', 'Un amendement à la loi sur la taxe sur la valeur ajoutée et non-valeur ajoutée (Business Tax Act), publié le 3 septembre 2024, a formalisé les délais de transmission déjà en vigueur pour les eGUI : les factures B2B doivent être transmises à la plateforme du MOF dans un délai de 7 jours calendaires, et les factures B2C dans un délai de 2 jours calendaires. Il a également renforcé les sanctions pour transmission tardive ou manquante et pour données de facture inexactes, avec des amendes allant de 1 500 à 15 000 TWD et des sanctions croissantes en cas de récidive. Il s''agit d''un changement procédural et d''application -- il ne modifie pas le champ des entités couvertes par le mandat universel de 2021.', '["Vérifiez que votre flux de facturation transmet les eGUI B2B dans un délai de 7 jours et les B2C dans un délai de 2 jours après émission.", "Revoyez les procédures de correction d''erreurs -- des données transmises inexactes peuvent entraîner des sanctions distinctes des amendes pour transmission tardive.", "Prévoyez des amendes de 1 500 à 15 000 TWD par infraction comme risque de conformité si les processus de transmission ne sont pas automatisés."]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('tw-mig4-mandatory-2026', 'fr', 'Le MIG 4.0 devient le seul format eGUI valide', 'Le Message Implementation Guideline (MIG) version 4.0 a été introduit comme nouvelle norme de format XML pour l''eGUI à compter du 1er janvier 2024, fonctionnant en parallèle des anciens formats MIG 3.1/3.2 pendant une période de transition. Cette période de transition s''est achevée le 31 décembre 2025 -- depuis le 1er janvier 2026, les soumissions au format MIG 3.1/3.2 ne sont plus acceptées et le MIG 4.0 est le seul format valide pour la transmission des eGUI. Il s''agit d''une mise à niveau technique de format, pas d''un changement du périmètre couvert par le mandat.', '["Vérifiez que la sortie eGUI de votre système de facturation ou ERP a été mise à niveau vers le MIG 4.0 -- les soumissions au format MIG 3.1/3.2 sont désormais rejetées.", "Si un éditeur de logiciel ou un prestataire certifié gère la transmission pour votre compte, vérifiez qu''il a achevé la migration vers le MIG 4.0 avant la bascule."]');
